/* @lc app=leetcode id=4026 lang=kotlin */ class Solution { fun maximumGap(skill: String, station: String): Int = skill.runningFold(-1) { a, c -> station.indexOf(c, a + 1) }.drop(1).let { L -> skill.reversed().runningFold(station.length) { a, c -> station.lastIndexOf(c, a - 1) }.drop(1).reversed().let { R -> (1 until skill.length).maxOfOrNull { R[it] - L[it - 1] } ?: 0 } } }